library(rootSolve)

R <- 2
delta <- 1 / 6

f <- function(z, lambda) {
  x <- z[1]
  y <- z[2]

  dx <- delta * (1 - x) - x / lambda * abs(-y + R * x)
  dy <- 1 - y - y / lambda * abs(-y + R * x)

  c(dx, dy)
}

find_eq <- function(lambda) {
  xstart <- seq(-0.5, 1.5, length = 6)
  ystart <- seq(-0.5, 1.5, length = 6)
  sols <- list()

  for (xs in xstart) {
    for (ys in ystart) {
      out <- try(
        multiroot(f,
          start = c(xs, ys),
          lambda = lambda
        ),
        silent = TRUE
      )

      if (!inherits(out, "try-error")) {
        root <- out$root

        # --- convergence check ---
        res <- f(root, lambda)
        if (max(abs(res)) < 1e-6) { # tolerance
          sols[[length(sols) + 1]] <- root
        }
      }
    }
  }

  if (length(sols) == 0) {
    return(NULL)
  }
  unique(round(do.call(rbind, sols), 4))
}


# sweep lambda
lambdas <- seq(0.01, 0.4, by = 0.01)
results <- data.frame()

for (lam in lambdas) {
  eq <- find_eq(lam)
  if (is.null(eq)) next

  results <- rbind(
    results,
    data.frame(
      lambda = lam,
      x = eq[, 1],
      y = eq[, 2]
    )
  )
}

par(mfrow = c(1, 2))
# plot bifurcation diagram (x equilibrium)
plot(results$lambda, results$x,
  pch = 16,
  xlab = expression(lambda),
  ylab = "Equilibrium x",
  main = "(a) Temperature contrast (x)"
)
grid()

plot(results$lambda, results$y,
  pch = 16,
  xlab = expression(lambda),
  ylab = "Equilibrium y",
  main = "(b) Salinity contrast (y)"
)
grid()
